import React, { useState, useEffect } from 'react';

const Grid = ({ onGridItemClick }) => {
    const [gridData, setGridData] = useState([]);

    useEffect(() => {
        fetch('/gridData.json')
            .then((response) => response.json())
            .then((data) => {
                console.log('Fetched JSON data:', data);
                setGridData(data);
            })
            .catch((error) => console.error('Error fetching grid data:', error));
    }, []);

    const filteredItems = gridData.filter(item => !item.empty);

    if (filteredItems.length > 0) {
        const firstItem = filteredItems[1]; // Use the first item that has image data
        return (
            <div className="image-grid">
                <div
                    className="grid-item"
                    key={0}
                    onClick={() => onGridItemClick(firstItem.text, firstItem.carousel ? firstItem.images : [firstItem.image], firstItem.carousel)}
                >
                    {firstItem.carousel ? (
                        firstItem.images && firstItem.images.length > 0 && (
                            <img src={firstItem.images[0]} alt={firstItem.text} />
                        )
                    ) : (
                        firstItem.image && (
                            <img src={firstItem.image} alt={firstItem.text} />
                        )
                    )}
                </div>
            </div>
        );
    } else {
        return <div>No items to display.</div>;
    }
};

export default Grid;
